def calculate_S(n, p, q):
    return (12 + n) / p + (13 - n) / q

max_S = -float('inf')
found_solutions = []

# Test all combinations for n in [1, 12], p in [1, 3], q in [1, 3]
for n in range(1, 13):
    for p in [1, 2, 3]:
        for q in [1, 2, 3]:
            S = calculate_S(n, p, q)
            if S < 1:
                if S > max_S:
                    max_S = S
                found_solutions.append((S, n, p, q))

print(f"Maximum S found: {max_S}")
